BEGIN;

CREATE TABLE account (
    account_id        bigserial PRIMARY KEY,
    name              varchar(255) NOT NULL,
    email             varchar(255) NOT NULL,
    email_verified_at timestamptz,
    password          varchar(255) NOT NULL,
    remember_token    varchar(100),
    avatar_url        varchar(255),
    timezone          varchar(64) NOT NULL DEFAULT 'America/Bogota',
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_account_email UNIQUE (email)
);

CREATE TABLE team (
    team_id     bigserial PRIMARY KEY,
    name        varchar(120) NOT NULL,
    slug        varchar(120) NOT NULL,
    owner_id    bigint NOT NULL REFERENCES account (account_id) ON DELETE RESTRICT,
    archived_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_team_slug UNIQUE (slug)
);

CREATE TABLE team_member (
    team_id    bigint NOT NULL REFERENCES team (team_id) ON DELETE CASCADE,
    account_id bigint NOT NULL REFERENCES account (account_id) ON DELETE CASCADE,
    role       varchar(20) NOT NULL DEFAULT 'member',
    joined_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (team_id, account_id),
    CONSTRAINT ck_team_member_role CHECK (role IN ('owner', 'admin', 'member'))
);

CREATE INDEX ix_team_member_account ON team_member (account_id);

CREATE TABLE project (
    project_id  bigserial PRIMARY KEY,
    team_id     bigint NOT NULL REFERENCES team (team_id) ON DELETE CASCADE,
    name        varchar(80) NOT NULL,
    color       varchar(7),
    archived_at timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_project_team_name UNIQUE (team_id, name),
    CONSTRAINT uq_project_id_team UNIQUE (project_id, team_id)
);

CREATE INDEX ix_project_team ON project (team_id);

CREATE TABLE task (
    task_id      bigserial PRIMARY KEY,
    team_id      bigint REFERENCES team (team_id) ON DELETE CASCADE,
    project_id   bigint,
    created_by   bigint NOT NULL REFERENCES account (account_id) ON DELETE RESTRICT,
    title        varchar(120) NOT NULL,
    description  text,
    status       varchar(20) NOT NULL DEFAULT 'pendiente',
    priority     varchar(20) NOT NULL DEFAULT 'media',
    start_date   date NOT NULL,
    end_date     date NOT NULL,
    completed_at timestamptz,
    position     integer NOT NULL DEFAULT 0,
    deleted_at   timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT ck_task_status CHECK (status IN ('pendiente', 'en_progreso', 'completada')),
    CONSTRAINT ck_task_priority CHECK (priority IN ('baja', 'media', 'alta')),
    CONSTRAINT ck_task_dates CHECK (end_date >= start_date),
    CONSTRAINT ck_task_completed CHECK ((status = 'completada') = (completed_at IS NOT NULL)),
    CONSTRAINT ck_task_personal CHECK (project_id IS NULL OR team_id IS NOT NULL),
    CONSTRAINT fk_task_project_team FOREIGN KEY (project_id, team_id)
        REFERENCES project (project_id, team_id) ON DELETE RESTRICT
);

CREATE INDEX ix_task_team_status ON task (team_id, status) WHERE deleted_at IS NULL;
CREATE INDEX ix_task_calendar ON task (team_id, start_date, end_date) WHERE deleted_at IS NULL;
CREATE INDEX ix_task_personal_calendar ON task (created_by, start_date, end_date) WHERE team_id IS NULL;
CREATE INDEX ix_task_project ON task (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX ix_task_created_by ON task (created_by);

CREATE TABLE task_assignee (
    task_id     bigint NOT NULL REFERENCES task (task_id) ON DELETE CASCADE,
    account_id  bigint NOT NULL REFERENCES account (account_id) ON DELETE CASCADE,
    assigned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (task_id, account_id)
);

CREATE INDEX ix_task_assignee_account ON task_assignee (account_id);

CREATE TABLE subtask (
    subtask_id  bigserial PRIMARY KEY,
    task_id     bigint NOT NULL REFERENCES task (task_id) ON DELETE CASCADE,
    title       varchar(160) NOT NULL,
    is_done     boolean NOT NULL DEFAULT false,
    position    integer NOT NULL DEFAULT 0,
    assignee_id bigint REFERENCES account (account_id) ON DELETE SET NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX ix_subtask_task_position ON subtask (task_id, position);












































SELECT setval(pg_get_serial_sequence('account', 'account_id')::regclass, (SELECT max(account_id) FROM account));
SELECT setval(pg_get_serial_sequence('team', 'team_id')::regclass, (SELECT max(team_id) FROM team));
SELECT setval(pg_get_serial_sequence('project', 'project_id')::regclass, (SELECT max(project_id) FROM project));
SELECT setval(pg_get_serial_sequence('task', 'task_id')::regclass, (SELECT max(task_id) FROM task));
SELECT setval(pg_get_serial_sequence('subtask', 'subtask_id')::regclass, (SELECT max(subtask_id) FROM subtask));

COMMIT;

SELECT a.name AS persona, count(*) AS tareas
FROM account AS a
INNER JOIN task_assignee AS ta ON ta.account_id = a.account_id
INNER JOIN task AS t ON t.task_id = ta.task_id
GROUP BY a.account_id, a.name
ORDER BY tareas DESC;

SELECT e.name AS equipo, count(*) AS tareas
FROM team AS e
INNER JOIN task AS t ON t.team_id = e.team_id
GROUP BY e.team_id, e.name
ORDER BY tareas DESC;

SELECT t.start_date AS dia, count(*) AS tareas
FROM task AS t
GROUP BY t.start_date
ORDER BY t.start_date;
